python3 - <<'PY'
import zipfile
import xml.etree.ElementTree as ET
import openpyxl
from openpyxl.utils import get_column_letter

src='/root/data/workbook.xlsx'
intermediate='/root/output/result_unpatched.xlsx'
out='/root/output/result.xlsx'

# ---- Write formulas ----
wb=openpyxl.load_workbook(src, data_only=False)
ws_task=wb['Task']
ws_data=wb['Data']
year_header_row=4

def set_lookup_formulas(row_start, row_end):
    for r in range(row_start, row_end+1):
        for c in range(8, 13):
            col_letter=get_column_letter(c)
            ws_task.cell(r,c).value=(
                f"=INDEX(Data!$H$21:$L$38,"
                f"MATCH($D{r},Data!$D$21:$D$38,0),"
                f"MATCH({col_letter}$10,Data!$H${year_header_row}:$L${year_header_row},0))"
            )

set_lookup_formulas(12,17)
set_lookup_formulas(19,24)
set_lookup_formulas(26,31)

for i in range(6):
    out_row=35+i
    adm_row=12+i
    dis_row=19+i
    cap_row=26+i
    for c in range(8,13):
        col=get_column_letter(c)
        ws_task.cell(out_row,c).value=f"=({col}{adm_row}-{col}{dis_row})/{col}{cap_row}*100"

label_to_kind={
    'minimum':'min',
    'maximum':'max',
    'median':'median',
    'simple mean':'mean',
    '25th percentile':'p25',
    '75th percentile':'p75',
}
row_to_kind={}
for r in range(42,48):
    label=ws_task.cell(r,5).value  # E
    if label is None:
        continue
    key=str(label).strip().lower()
    if key not in label_to_kind:
        raise RuntimeError(f"Unrecognized stat label at E{r}: {label!r}")
    row_to_kind[r]=label_to_kind[key]

kind_to_formula={
    'min': lambda col: f"=MIN({col}35:{col}40)",
    'max': lambda col: f"=MAX({col}35:{col}40)",
    'median': lambda col: f"=MEDIAN({col}35:{col}40)",
    'mean': lambda col: f"=AVERAGE({col}35:{col}40)",
    'p25': lambda col: f"=PERCENTILE({col}35:{col}40,0.25)",
    'p75': lambda col: f"=PERCENTILE({col}35:{col}40,0.75)",
}

for r, kind in row_to_kind.items():
    for c in range(8,13):
        col=get_column_letter(c)
        ws_task.cell(r,c).value=kind_to_formula[kind](col)

for c in range(8,13):
    col=get_column_letter(c)
    ws_task.cell(50,c).value=f"=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)"

wb.save(intermediate)

# ---- Compute values ----
years=[ws_data.cell(year_header_row,c).value for c in range(8,13)]
if any(y is None for y in years):
    raise RuntimeError('Missing years')

series_year_to_val={}
for r in range(21,39):
    code=ws_data.cell(r,4).value
    if not code:
        continue
    for j,c in enumerate(range(8,13)):
        y=years[j]
        v=ws_data.cell(r,c).value
        series_year_to_val[(code,y)]=float(v)

# helpers

def median(vals):
    s=sorted(vals)
    n=len(s)
    if n%2:
        return float(s[n//2])
    return float((s[n//2-1]+s[n//2])/2)

def percentile_inc(vals,k):
    s=sorted(vals)
    n=len(s)
    if k<=0: return float(s[0])
    if k>=1: return float(s[-1])
    rank=(n-1)*k+1
    ir=int(rank)
    frac=rank-ir
    if frac==0:
        return float(s[ir-1])
    lo=s[ir-1]; hi=s[ir]
    return float(lo + frac*(hi-lo))

coord_to_value={}

# lookup blocks
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    code=ws_task.cell(r,4).value
    for c in range(8,13):
        year=ws_task.cell(10,c).value
        coord=f"{get_column_letter(c)}{r}"
        coord_to_value[coord]=series_year_to_val[(code,year)]

# net flow
for i in range(6):
    adm_row=12+i; dis_row=19+i; cap_row=26+i; out_row=35+i
    for c in range(8,13):
        col=get_column_letter(c)
        adm=coord_to_value[f"{col}{adm_row}"]
        dis=coord_to_value[f"{col}{dis_row}"]
        cap=coord_to_value[f"{col}{cap_row}"]
        coord_to_value[f"{col}{out_row}"]=(adm-dis)/cap*100.0

# stats
for c in range(8,13):
    col=get_column_letter(c)
    flows=[coord_to_value[f"{col}{35+i}"] for i in range(6)]
    for r, kind in row_to_kind.items():
        if kind=='min': v=min(flows)
        elif kind=='max': v=max(flows)
        elif kind=='median': v=median(flows)
        elif kind=='mean': v=sum(flows)/len(flows)
        elif kind=='p25': v=percentile_inc(flows,0.25)
        elif kind=='p75': v=percentile_inc(flows,0.75)
        else: raise RuntimeError(kind)
        coord_to_value[f"{col}{r}"]=v

# weighted mean
for c in range(8,13):
    col=get_column_letter(c)
    flows=[coord_to_value[f"{col}{35+i}"] for i in range(6)]
    caps=[coord_to_value[f"{col}{26+i}"] for i in range(6)]
    coord_to_value[f"{col}50"]=sum(f*w for f,w in zip(flows,caps))/sum(caps)

# ---- Patch xml cached values ----
ns_main='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
ns_rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
NS={'m':ns_main,'r':ns_rel}

with zipfile.ZipFile(intermediate,'r') as zin:
    wb_xml=ET.fromstring(zin.read('xl/workbook.xml'))
    sheets=wb_xml.find('m:sheets',NS)
    task_rid=None
    for sh in sheets.findall('m:sheet',NS):
        if sh.attrib.get('name')=='Task':
            task_rid=sh.attrib.get(f'{{{ns_rel}}}id')
            break
    if not task_rid:
        raise RuntimeError('Task r:id not found')

    rels=ET.fromstring(zin.read('xl/_rels/workbook.xml.rels'))
    pkg_rel_ns='http://schemas.openxmlformats.org/package/2006/relationships'
    target=None
    for rel in rels.findall(f'{{{pkg_rel_ns}}}Relationship'):
        if rel.attrib.get('Id')==task_rid:
            target=rel.attrib.get('Target')
            break
    if not target:
        raise RuntimeError('Task target not found')

    # Normalize to actual zip path
    target=target.lstrip('/')
    if target.startswith('xl/'):
        task_sheet_path=target
    else:
        task_sheet_path='xl/'+target

    task_root=ET.fromstring(zin.read(task_sheet_path))
    sheetData=task_root.find('m:sheetData',NS)

    updated=0
    for row in sheetData.findall('m:row',NS):
        for c_el in row.findall('m:c',NS):
            coord=c_el.attrib.get('r')
            if coord not in coord_to_value:
                continue
            f_el=c_el.find('m:f',NS)
            if f_el is None:
                continue
            v_el=c_el.find('m:v',NS)
            if v_el is None:
                v_el=ET.SubElement(c_el, f'{{{ns_main}}}v')
            v_el.text=('%.15g' % coord_to_value[coord])
            updated+=1

    with zipfile.ZipFile(out,'w',compression=zipfile.ZIP_DEFLATED) as zout:
        for info in zin.infolist():
            content=zin.read(info.filename)
            if info.filename==task_sheet_path:
                zout.writestr(info, ET.tostring(task_root, encoding='utf-8', xml_declaration=True))
            else:
                zout.writestr(info, content)

print('Patched cells:', updated)

# ---- Validate cached values ----
wb_do=openpyxl.load_workbook(out, data_only=True)
ws=wb_do['Task']
print('data_only values:', {a: ws[a].value for a in ['H12','H19','H26','H35','H42','H50']})
wb_nf=openpyxl.load_workbook(out, data_only=False)
ws2=wb_nf['Task']
print('formulas:', {a: ws2[a].value for a in ['H12','H19','H26','H35','H42','H50']})
print('Sheets:', wb_do.sheetnames)

# formatting spot-check
wb_src=openpyxl.load_workbook(src, data_only=False)
ws_src=wb_src['Task']

def fill_sig(f):
    return (f.patternType, getattr(f.fgColor,'rgb',None), getattr(f.bgColor,'rgb',None), getattr(f.fgColor,'indexed',None))

print('Fill check:')
for addr in ['H12','I12','H35','H42','H50']:
    print(addr, fill_sig(ws_src[addr].fill), fill_sig(ws2[addr].fill))
PY
